  "tradeOffs": [
    {
      "choice": "Keep one token bucket per key in a shared store instead of one bucket per gateway node",
      "gains": "Every gateway enforces the same limit across 24 nodes.",
      "costs": "Every request pays a network round trip: 0.4 ms at the median and 2.1 ms at p99 in June 2024 measurements.",
      "sourceChunkIds": [
        "source-1#chunk-2"
      ]
    },
    {
      "choice": "Use a token bucket instead of a fixed-window counter",
      "gains": "Bursts are bounded by the bucket's capacity no matter where the clock is.",
      "costs": "The bucket needs extra state per key and an atomic read-modify-write in the shared store; the fixed window needed only one counter per key.",
      "sourceChunkIds": [
        "source-1#chunk-1",
        "source-1#chunk-2"
      ]
    },
    {
      "choice": "Let a quiet client burst up to the bucket's full capacity",
      "gains": "Clients that have been idle can send a burst without waiting.",
      "costs": "A client can send that entire burst at once, so short spikes up to capacity still pass.",
      "sourceChunkIds": [
        "source-1#chunk-1"
      ]
    },
    {
      "choice": "Fail open when the limiter store is slow",
      "gains": "Checkout does not refuse payments just because the limiter store is slow.",
      "costs": "Each of 40 checkout instances enforces the full limit locally, so traffic can reach roughly 40 times the contracted 300 requests per second and the provider throttles all traffic.",
      "sourceChunkIds": [
        "source-3#chunk-1",
        "source-3#chunk-2"
      ]
    },
    {
      "choice": "Fail closed when the limiter store is slow",
      "gains": "The service refuses traffic it cannot count instead of exceeding a downstream contract.",
      "costs": "Requests are refused with 503, and a slow store delays some payments instead of breaking all of them.",
      "sourceChunkIds": [
        "source-2#chunk-2",
        "source-3#chunk-2"
      ]
    },
    {
      "choice": "Enable local fallback while the shared store is down",
      "gains": "Each instance can keep serving when the shared store is unavailable.",
      "costs": "The effective limit is multiplied by the number of instances unless those local limits are divided.",
      "sourceChunkIds": [
        "source-2#chunk-2",
        "source-3#chunk-2"
      ]
    },
    {
      "choice": "Use a sliding window log for exact counting",
      "gains": "It stores every request timestamp and counts them exactly, with no burst allowance.",
      "costs": "Memory grows with the limit: at 8 bytes per timestamp, 1,000 requests per minute costs about 8 KB per active key, and 500,000 active keys cost around 4 GB.",
      "sourceChunkIds": [
        "source-2#chunk-1"
      ]
    },
    {
